function resolveUser(body) {
  const crypto = require('crypto');
  try {
    if (body.init_data) {
      // ручной разбор строки initData (без стандартного URL-парсера:
      // в песочнице Code node он недоступен);
      // data_check_string строится из СЫРЫХ значений, как требует Telegram
      const raw = String(body.init_data);
      let hash = '';
      const pairs = [];
      for (const part of raw.split('&')) {
        const eq = part.indexOf('=');
        if (eq < 0) continue;
        const k = part.slice(0, eq);
        const v = part.slice(eq + 1);
        if (k === 'hash') { hash = v; continue; }
        if (k === 'signature') continue;
        pairs.push([k, v]);
      }
      const dcs = pairs.map(([k, v]) => k + '=' + v).sort().join('&');
      const secret = crypto.createHmac('sha256', 'WebAppData').update('__BOT_TOKEN__').digest();
      const calc = crypto.createHmac('sha256', secret).update(dcs).digest('hex');
      if (!hash || calc !== hash) return null;
      const uv = (pairs.find(([k]) => k === 'user') || [])[1] || '{}';
      const u = JSON.parse(decodeURIComponent(uv));
      return u.username ? '@' + String(u.username) : (u.id ? String(u.id) : null);
    }
    if (body.user && body.sig) {
      const calc = crypto.createHmac('sha256', '__SIGN_SECRET__').update(String(body.user)).digest('hex');
      return calc === String(body.sig) ? String(body.user) : null;
    }
  } catch (e) {
    return null;
  }
  return null;
}
const body = $input.first().json.body || {};
const text = String(body.text || '').slice(0, 2000);
if (!text.trim()) {
  // пустой текст — честный ответ вместо HTTP 500
  return [{ json: { ok: false, error: 'Опишите задачу — отправьте текст заявки' } }];
}
const uid = resolveUser(body);
return [{ json: { text, user: uid ? uid.slice(0, 64) : null } }];

const r = $input.first().json;
let content = '';
try { content = String(r.choices[0].message.content || ''); } catch (e) {}
// LLM любит заворачивать JSON в ```-фенсы — срезаем
content = content.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
let parsed = null;
try { parsed = JSON.parse(content); } catch (e) {}
if (!parsed || typeof parsed !== 'object') {
  // не ломаемся в мусорный лид: безопасный «не заявка» с подсказкой
  return [{ json: { ok: true, category: 'прочее', priority: 'средний',
    summary: 'не удалось разобрать ответ модели — попробуйте переформулировать',
    is_request: false, needs_clarification: false, clarify_question: '', lead_saved: false } }];
}
parsed.is_request = parsed.is_request === true || parsed.is_request === 'true';
parsed.needs_clarification = parsed.needs_clarification === true || parsed.needs_clarification === 'true';
parsed.clarify_question = String(parsed.clarify_question || '');
return [{ json: { ok: true, ...parsed } }];

// Лид-захват: каждая классифицированная заявка попадает в очередь менеджера
